link.script:
//
nowViewing = 1;
currentChapter = 1;

function highLightChapter()
{
	if(nowViewing > 38)
	{
		currentChapter.className = "unselected";
		currentChapter = document.getElementById("jump4");
		currentChapter.className = "selected";
	}
	if(nowViewing < 39)
	{
		currentChapter.className = "unselected";
		currentChapter = document.getElementById("jump3");
		currentChapter.className = "selected";
	}
	if(nowViewing < 22)
	{
		currentChapter.className = "unselected";
		currentChapter = document.getElementById("jump2");
		currentChapter.className = "selected";
	}
	if(nowViewing < 13)
	{
		currentChapter.className = "unselected";
		currentChapter = document.getElementById("jump1");
		currentChapter.className = "selected";
	}
	if(nowViewing < 2)
	{
		currentChapter.className = "unselected";
		currentChapter = document.getElementById("jump0");
		currentChapter.className = "selected";
	}
}

function chapterPaging()
{
	document.getElementById("currentPage").innerHTML = nowViewing;
	document.getElementById("currentChapter").innerHTML = document.getElementById("chapter"+nowViewing).innerHTML;
	document.getElementById("chapterBG").style.height = Math.max(document.getElementById("currentChapter").scrollHeight,725) + "px";
	document.getElementById("contentRoot").style.height = Math.max(document.getElementById("currentChapter").scrollHeight,725)+ 300 + "px";
	document.getElementById("progressBar").style.width = (nowViewing/41)*266 + "px";
	highLightChapter();
}

function loadNextChapter()
{
	if(nowViewing < 41) 
	{
		nowViewing++;
		chapterPaging();
	}
}

function loadPrevChapter()
{
	if(nowViewing > 1)
	{
		nowViewing--;
		chapterPaging();
	}
}

function loadChapter(thisChapter)
{
	document.getElementById("currentChapter").innerHTML = document.getElementById("chapter"+thisChapter).innerHTML;
	nowViewing = thisChapter;
	document.getElementById("currentPage").innerHTML = nowViewing;
	document.getElementById("chapterBG").style.height = Math.max(document.getElementById("currentChapter").scrollHeight,725) + "px";
	document.getElementById("contentRoot").style.height = Math.max(document.getElementById("currentChapter").scrollHeight,725)+300 + "px";
	document.getElementById("progressBar").style.width = (nowViewing/41)*266 + "px";
	highLightChapter();
}

document.onload = window.setTimeout("loadChapter(2)",62);

//
